   var shadow=r;shadow.Offset(0,6);shadow.Inflate(4,0);Visual.Fill(g,shadow,radius+2,Color.FromArgb(20,22,31));Visual.Fill(g,r,radius,Color.FromArgb(online?49:32,online?49:35,online?68:46));Visual.Stroke(g,r,radius,border,source&&online?2:1.5f);
   var screen=r;screen.Inflate(phone?-6:-7,phone?-9:-7);if(screen.Width>1&&screen.Height>1){using(var path=Visual.Round(screen,Math.Max(3,radius-5)))using(var gradient=new LinearGradientBrush(screen,!online?Color.FromArgb(34,37,49):source?Color.FromArgb(66,49,105):Color.FromArgb(38,55,81),!online?Color.FromArgb(29,32,42):source?Color.FromArgb(35,35,64):Color.FromArgb(30,34,53),45)){g.FillPath(gradient,path);}if(online){var state=g.Save();g.SetClip(Visual.Round(screen,Math.Max(3,radius-5)));using(var arc=new Pen(Color.FromArgb(28,173,155,235),Math.Max(16,screen.Width*.17f)))g.DrawEllipse(arc,screen.X+screen.Width*.28f,screen.Y-screen.Height*.38f,screen.Width,screen.Height*1.7f);g.Restore(state);}}
   if(phone){using(var pen=new Pen(border,2)){g.DrawLine(pen,r.X+r.Width*.37f,r.Y+7,r.X+r.Width*.63f,r.Y+7);g.DrawLine(pen,r.X+r.Width*.33f,r.Bottom-6,r.X+r.Width*.67f,r.Bottom-6);}}
   else{using(var path=new GraphicsPath()){path.AddPolygon(new[]{new PointF(r.Left-10,r.Bottom+4),new PointF(r.Right+10,r.Bottom+4),new PointF(r.Right+3,r.Bottom+10),new PointF(r.Left-3,r.Bottom+10)});using(var brush=new SolidBrush(border))g.FillPath(brush,path);}Visual.Fill(g,new RectangleF(r.X+r.Width*.36f,r.Bottom+3,r.Width*.28f,3),1,Color.FromArgb(29,31,42));}
   if(source&&online){float cx=r.X+r.Width/2,cy=r.Y+r.Height/2;using(var pen=new Pen(Color.FromArgb(202,190,253),1.5f)){var keyboard=new RectangleF(cx-18,cy-10,36,23);g.DrawRectangle(pen,keyboard.X,keyboard.Y,keyboard.Width,keyboard.Height);for(int y=0;y<2;y++)for(int x=0;x<5;x++)g.DrawLine(pen,cx-13+x*6,cy-5+y*5,cx-11+x*6,cy-5+y*5);g.DrawLine(pen,cx-10,cy+7,cx+10,cy+7);}}
   if(!online)Visual.Text(g,"Z z",new RectangleF(r.X,r.Y+r.Height/2-14,r.Width,28),21,Color.FromArgb(100,106,127),false,StringAlignment.Center);
   float labelWidth=Math.Max(r.Width+16,132),labelX=r.X+r.Width/2-labelWidth/2;Visual.Text(g,d.name,new RectangleF(labelX,r.Bottom+19,labelWidth,24),14,online?Color.FromArgb(232,232,242):MainForm.Muted,true,StringAlignment.Center);Visual.Text(g,!online?"Offline":source?"●  Input source":d.id==Network.LocalId?"This PC":"Ready",new RectangleF(labelX,r.Bottom+44,labelWidth,21),12,source&&online?Color.FromArgb(176,156,255):MainForm.Muted,false,StringAlignment.Center);
