 }
 static GraphicsPath Round(RectangleF r,float radius){var p=new GraphicsPath();float d=Math.Min(radius*2,Math.Min(r.Width,r.Height));p.AddArc(r.X,r.Y,d,d,180,90);p.AddArc(r.Right-d,r.Y,d,d,270,90);p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);p.AddArc(r.X,r.Bottom-d,d,d,90,90);p.CloseFigure();return p;}
 protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);Selected=session.Devices.LastOrDefault(d=>Card(d).Contains(e.Location));start=e.Location;moved=false;if(Selected!=null){originalX=Selected.x;originalY=Selected.y;Capture=true;}if(SelectionChanged!=null)SelectionChanged();Invalidate();}
 protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);if(!Capture||Selected==null)return;if(Math.Abs(e.X-start.X)+Math.Abs(e.Y-start.Y)>6)moved=true;if(moved){Selected.x=Math.Max(-5000,Math.Min(5000,originalX+(e.X-start.X)/scale));Selected.y=Math.Max(-5000,Math.Min(5000,originalY+(e.Y-start.Y)/scale));Invalidate();if(SelectionChanged!=null)SelectionChanged();}}
 protected override void OnMouseUp(MouseEventArgs e){base.OnMouseUp(e);Capture=false;if(Selected!=null&&moved){foreach(var d in session.Devices){if(d==Selected)continue;var a=Selected.Bounds;var b=d.Bounds;if(Math.Abs(a.Left-b.Right)<18)Selected.x=b.Right;if(Math.Abs(a.Right-b.Left)<18)Selected.x=b.Left-a.Width;if(Math.Abs(a.Top-b.Bottom)<18)Selected.y=b.Bottom;if(Math.Abs(a.Bottom-b.Top)<18)Selected.y=b.Top-a.Height;}session.Position(Selected.id,Selected.x,Selected.y);}Invalidate();}
 protected override void OnDoubleClick(EventArgs e){base.OnDoubleClick(e);if(Selected==null||!Selected.online||!session.Input.Enabled)return;session.Input.Select(Selected.id==Network.LocalId?null:session.Input.Order.Find(p=>p!=null&&p.Id==Selected.id));}
}
public static class EdgeTest {
 public static void Run(){using(var form=new Form()){form.Shown+=(s,e)=>{foreach(var screen in Screen.AllScreens){var b=screen.Bounds;foreach(var r in new[]{new Rectangle(b.Left,b.Top,6,b.Height),new Rectangle(b.Right-6,b.Top,6,b.Height),new Rectangle(b.Left,b.Top,b.Width,6),new Rectangle(b.Left,b.Bottom-6,b.Width,6)})using(var edge=new Edge(r,Color.Cyan)){edge.Show();Application.DoEvents();Native.RECT actual;Native.GetWindowRect(edge.Handle,out actual);if(actual.Left!=r.Left||actual.Top!=r.Top||actual.Right!=r.Right||actual.Bottom!=r.Bottom)throw new Exception("Overlay bounds mismatch: "+r+" vs "+actual.Left+","+actual.Top+","+actual.Right+","+actual.Bottom);}}File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"edge-test.txt"),"All four native overlay bounds match every monitor exactly.");form.Close();};Application.Run(form);}}
}
